class RiskSet {
  final int time, risk, events, censored;
  RiskSet(this.time, this.risk, this.events, this.censored);
}

List<RiskSet> riskSets(List<Subject> subjects) {
  final counts = <int, int>{}, events = <int, int>{};
  for (final s in subjects) {
    counts[s.time] = (counts[s.time] ?? 0) + 1;
    events[s.time] = (events[s.time] ?? 0) + s.event;
  }
  final times = counts.keys.toList()..sort(), rows = <RiskSet>[];
  var risk = subjects.length;
  for (final t in times) {
    rows.add(RiskSet(t, risk, events[t]!, counts[t]! - events[t]!));
    risk -= counts[t]!;
  }
  return rows;
}
class KMRow {
  final int time, risk, events, censored;
  final double survival, se, lower, upper, hazard, hazardSE;
  KMRow(
    this.time,
    this.risk,
    this.events,
    this.censored,
    this.survival,
    this.se,
    this.lower,
    this.upper,
    this.hazard,
    this.hazardSE,
  );
}

List<KMRow> kaplanMeier(List<Subject> subjects) {
  final times = riskSets(subjects),
      eventTimes = [
        for (final r in times)
          if (r.events > 0) r.time,
      ],
      rows = <KMRow>[];
  var survival = 1.0, greenwood = 0.0, hazard = 0.0, variance = 0.0;
  for (final r in times) {
    final n = r.risk, d = r.events;
    if (d == 0) continue;
    survival *= (n - d) / n;
    hazard += d / n;
    variance += d / (n * n);
    final index = rows.length;
    var censored = 0;
    for (final s in subjects) {
      if (s.event == 0 &&
          s.time >= r.time &&
          (index + 1 == eventTimes.length || s.time < eventTimes[index + 1]))
        censored++;
    }
    rows.add(
      KMRow(
        r.time,
        n,
        d,
        censored,
        survival,
        se,
        lo,
        hi,
        hazard,
        math.sqrt(variance),
      ),
    );
  }
  return rows;
}

KMRow rowAt(List<KMRow> rows, int t) {
  for (var j = rows.length - 1; j >= 0; j--) {
    if (rows[j].time <= t) return rows[j];
  }
  return KMRow(0, 0, 0, 0, 1, 0, double.nan, double.nan, 0, 0);
}
String number(double value) {
  if (value.isNaN) return 'NA';
  final s = value.toStringAsFixed(4);
int riskCount(List<Subject> subjects, int time) =>
    subjects.where((s) => s.time >= time).length;
  final rows = kaplanMeier(subjects),
  return Summary(
    rows,
      for (final time in params.times) {
        final r = rowAt(s.rows, time),
            events = rows
                .where((s) => s.time <= time)
                .fold(0, (sum, s) => sum + s.event);
        lines.add(
          'at $time at_risk ${riskCount(rows, time)} events $events survival ${number(r.survival)} std_err ${number(r.se)} lower ${number(r.lower)} upper ${number(r.upper)} cum_hazard ${number(r.hazard)} hazard_se ${number(r.hazardSE)}',
        );
      }
      for (final r in s.rows) {
        final fields = [
          '${r.time}',
          '${r.risk}',
          '${r.events}',
          '${r.censored}',
          number(r.survival),
          number(r.se),
          number(r.lower),
          number(r.upper),
          number(r.hazard),
          number(r.hazardSE),
        ];
        lines.add(fields.map((s) => s.padLeft(9)).join());
      }
